// Hand-written. Not generated by Speakeasy.
//
// Every JWK Set attribute must be compared by meaning rather than byte for
// byte, because Authlete returns a set with its whitespace stripped and its
// member keys reordered. Without the type the configured spelling and the
// stored one never match, so the attribute plans a change on every run and
// drags every computed attribute on the resource into the plan with it.
//
// This exists because the set was done one attribute at a time and one was
// missed: credential_jwks kept the plain string type through the whole beta.
// It is also marked sensitive, so its endless diff showed a change without
// showing anything that could explain it. A table covering all five removes
// the chance of the next one being missed too.
//
// Which type matters as much as having one. A service signs with its keys, so
// its sets are private. A client publishes its keys for Authlete to verify
// signatures with, and a trust anchor is a third party, so those two are
// public and carry the stricter type that refuses private material.
package provider

import (
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"

	"github.com/authlete/terraform-provider-authlete/v3/internal/provider/customtypes"
)

func TestEveryKeySetIsComparedByMeaning(t *testing.T) {
	service := resourceSchema(t, NewServiceResource()).Attributes
	client := resourceSchema(t, NewClientResource()).Attributes

	trustAnchor := func() schema.Attribute {
		nested, ok := service["trust_anchors"].(schema.ListNestedAttribute)
		if !ok {
			t.Fatalf("trust_anchors is %T, expected a list of nested objects", service["trust_anchors"])
		}
		return nested.NestedObject.Attributes["jwks"]
	}()

	for name, tc := range map[string]struct {
		attr schema.Attribute
		want attr.Type
		why  string
	}{
		"service jwks": {service["jwks"], customtypes.JWKSType{},
			"the keys the authorization server signs tokens with"},
		"service federation_jwks": {service["federation_jwks"], customtypes.JWKSType{},
			"the keys that sign entity statements"},
		"service credential_jwks": {service["credential_jwks"], customtypes.JWKSType{},
			"the keys that sign verifiable credentials"},
		"client jwks": {client["jwks"], customtypes.PublicJWKSType{},
			"a client publishes public keys, so private material is refused"},
		"trust anchor jwks": {trustAnchor, customtypes.PublicJWKSType{},
			"a trust anchor is a third party, so private material is refused"},
	} {
		t.Run(name, func(t *testing.T) {
			str, ok := tc.attr.(schema.StringAttribute)
			if !ok {
				t.Fatalf("%s is %T, expected a string attribute", name, tc.attr)
			}
			if str.CustomType == nil {
				t.Fatalf("%s has no custom type, so it is compared byte for byte "+
					"against a set Authlete has reordered: it plans a change on every "+
					"run.\n\nIt holds %s.\n\nAdd x-speakeasy-terraform-custom-type in "+
					".speakeasy/terraform_overlay.yaml and regenerate.", name, tc.why)
			}
			if !str.CustomType.Equal(tc.want) {
				t.Errorf("%s has custom type %T, want %T.\n\nIt holds %s.",
					name, str.CustomType, tc.want, tc.why)
			}
			if len(str.Validators) == 0 {
				t.Errorf("%s has no validators, so a malformed key set reaches Authlete", name)
			}
		})
	}
}
